import boto3
from typing import Dict, List, Any

def get_child_blocks(block: Dict[str, Any], block_map: Dict[str, Dict[str, Any]], child_block_type: str = None) -> List[Dict[str, Any]]:
    children = []
    for relationship in block.get('Relationships', []):
        if relationship['Type'] == 'CHILD':
            for child_id in relationship['Ids']:
                child = block_map[child_id]
                if child_block_type is None or child['BlockType'] == child_block_type:
                    children.append(child)
    return children

def get_text_from_block(block: Dict[str, Any], block_map: Dict[str, Dict[str, Any]]) -> str:
    text = block.get('Text', '')
    for child in get_child_blocks(block, block_map):
        text += ' ' + get_text_from_block(child, block_map)
    return text.strip()

def extract_tables(file_path: str) -> List[Dict[str, Any]]:
    client = boto3.client('textract', region_name='us-east-1')
    with open(file_path, 'rb') as file:
        document_bytes = file.read()

    response = client.analyze_document(
        Document={'Bytes': document_bytes},
        FeatureTypes=['TABLES']
    )

    blocks = response['Blocks']
    block_map = {block['Id']: block for block in blocks}

    tables = [block for block in blocks if block['BlockType'] == 'TABLE']
    table_structures = []

    for table in tables:
        rows = []
        row_blocks = get_child_blocks(table, block_map, 'ROW')
        for row_block in row_blocks:
            cell_blocks = get_child_blocks(row_block, block_map, 'CELL')
            row_cells = []
            for cell_block in cell_blocks:
                cell_text = get_text_from_block(cell_block, block_map)
                row_index = cell_block.get('RowIndex', 0)
                col_index = cell_block.get('ColumnIndex', 0)
                row_span = cell_block.get('RowSpan', 1)
                col_span = cell_block.get('ColumnSpan', 1)
                row_cells.append({
                    'text': cell_text,
                    'row_index': row_index,
                    'column_index': col_index,
                    'row_span': row_span,
                    'col_span': col_span
                })
            row_cells.sort(key=lambda c: c['column_index'])
            rows.append(row_cells)
        table_structures.append({'rows': rows})

    return table_structures
